import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Relative links in Markdown point at files that exist","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rules/no-dead-doc-links.md","filePath":"reference/rules/no-dead-doc-links.md"}`),a={name:`reference/rules/no-dead-doc-links.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="relative-links-in-markdown-point-at-files-that-exist" tabindex="-1">Relative links in Markdown point at files that exist <a class="header-anchor" href="#relative-links-in-markdown-point-at-files-that-exist" aria-label="Permalink to “Relative links in Markdown point at files that exist”">​</a></h1><p>Every relative link and image in a Markdown file resolves to a real file in the repository.</p><h2 id="why-it-is-a-rule" tabindex="-1">Why it is a rule <a class="header-anchor" href="#why-it-is-a-rule" aria-label="Permalink to “Why it is a rule”">​</a></h2><p>Documentation is the part of a change nothing type checks. Move or rename a source file and every import either updates or the build fails; a README that pointed at the old path keeps pointing at nothing, and the first person to notice is a reader months later. Automated refactors are especially prone to this, because they update every reference the compiler checks, and Markdown is not one of them.</p><h2 id="what-is-expected" tabindex="-1">What is expected <a class="header-anchor" href="#what-is-expected" aria-label="Permalink to “What is expected”">​</a></h2><p>Relative targets (<code>./docs/guide.md</code>, <code>../README.md</code>, <code>images/flow.png</code>) exist at the resolved path. A leading <code>/</code> resolves from the repository root. Anchors and queries are ignored: <code>guide.md#setup</code> checks only that <code>guide.md</code> exists.</p><p>External URLs, <code>mailto:</code> links and pure <code>#anchor</code> links are not checked; this rule only covers what a commit in this repository can break. Link syntax inside fenced code blocks and inline code spans is treated as example text and skipped.</p><h2 id="exceptions" tabindex="-1">Exceptions <a class="header-anchor" href="#exceptions" aria-label="Permalink to “Exceptions”">​</a></h2><p>A link that must point at a generated or git-ignored file (one that exists after a build but not in a fresh checkout) is better rewritten to point at the source that generates it. If that is not possible, exclude the document via the rule&#39;s <code>exclude</code> globs.</p>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};